import{a as e,c as t,i as n}from"./app-Cmb-X6oy.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E9%9D%A2%E8%AF%95%E9%A2%98/Mysql/0328-the-most-comprehensive-mysql-locks-in-history-including.html","title":"史上最全MySQL各种锁详解（含实战案例+排查优化）","lang":"zh-CN","frontmatter":{"title":"史上最全MySQL各种锁详解（含实战案例+排查优化）","sidebarGroup":"Mysql","shortTitle":"史上最全MySQL各种锁详解（含实战案例+排查优化）","order":328,"date":"2026-07-30T00:00:00.000Z","category":"面试题","tag":["面试题"],"description":"一、前言：为什么需要锁？在并发访问数据库时，多个事务同时读写数据会引发一系列问题（脏读、不可重复读、幻读、超卖等）。锁的核心作用是协调并发事务对共享资源的访问，通过控制资源的访问顺序，保证数据的一致性、完整性，是数据库并发控制的核心机制。本","article":false,"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"WebPage\\",\\"name\\":\\"史上最全MySQL各种锁详解（含实战案例+排查优化）\\",\\"description\\":\\"一、前言：为什么需要锁？在并发访问数据库时，多个事务同时读写数据会引发一系列问题（脏读、不可重复读、幻读、超卖等）。锁的核心作用是协调并发事务对共享资源的访问，通过控制资源的访问顺序，保证数据的一致性、完整性，是数据库并发控制的核心机制。本\\"}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/%E9%9D%A2%E8%AF%95%E9%A2%98/Mysql/0328-the-most-comprehensive-mysql-locks-in-history-including.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"史上最全MySQL各种锁详解（含实战案例+排查优化）"}],["meta",{"property":"og:description","content":"一、前言：为什么需要锁？在并发访问数据库时，多个事务同时读写数据会引发一系列问题（脏读、不可重复读、幻读、超卖等）。锁的核心作用是协调并发事务对共享资源的访问，通过控制资源的访问顺序，保证数据的一致性、完整性，是数据库并发控制的核心机制。本"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:image","content":"https://www.code-corey.com/面试题/Mysql/0328-the-most-comprehensive-mysql-locks-in-history-including/img-46a9121f0ed6.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-09T03:10:04.000Z"}],["meta",{"property":"article:tag","content":"面试题"}],["meta",{"property":"article:published_time","content":"2026-07-30T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-09T03:10:04.000Z"}]]},"git":{"createdTime":1786240216000,"updatedTime":1786245004000,"contributors":[{"name":"langkemaoxin","username":"langkemaoxin","email":"2363613998@qq.com","commits":3,"url":"https://github.com/langkemaoxin"},{"name":"Cursor","username":"Cursor","email":"cursoragent@cursor.com","commits":3,"url":"https://github.com/Cursor"}]},"readingTime":{"minutes":31.25,"words":9374},"filePathRelative":"面试题/Mysql/0328-the-most-comprehensive-mysql-locks-in-history-including.md","excerpt":"<blockquote>\\n<p>来源：<a href=\\"https://www.yuque.com/tulingzhouyu/db22bv/tz18319lfzvb4dbr\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">史上最全MySQL各种锁详解（含实战案例+排查优化）</a></p>\\n</blockquote>\\n<h1><strong>一、前言：为什么需要锁？</strong></h1>\\n<p>在并发访问数据库时，多个事务同时读写数据会引发一系列问题（脏读、不可重复读、幻读、超卖等）。锁的核心作用是<strong>协调并发事务对共享资源的访问</strong>，通过控制资源的访问顺序，保证数据的一致性、完整性，是数据库并发控制的核心机制。</p>"}`),a={name:`0328-the-most-comprehensive-mysql-locks-in-history-including.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p>来源：<a href="https://www.yuque.com/tulingzhouyu/db22bv/tz18319lfzvb4dbr" target="_blank" rel="noopener noreferrer">史上最全MySQL各种锁详解（含实战案例+排查优化）</a></p></blockquote><h1 id="一、前言-为什么需要锁" tabindex="-1"><a class="header-anchor" href="#一、前言-为什么需要锁"><span><strong>一、前言：为什么需要锁？</strong></span></a></h1><p>在并发访问数据库时，多个事务同时读写数据会引发一系列问题（脏读、不可重复读、幻读、超卖等）。锁的核心作用是<strong>协调并发事务对共享资源的访问</strong>，通过控制资源的访问顺序，保证数据的一致性、完整性，是数据库并发控制的核心机制。</p><p>本笔记基于MySQL 8.0版本，全面拆解锁的分类、实现原理、实战案例、排查工具及优化策略，兼顾理论深度与生产实操，适配面试与工作需求。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/Mysql/0328-the-most-comprehensive-mysql-locks-in-history-including/img-46a9121f0ed6.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="二、按锁的粒度分类-核心分类方式" tabindex="-1"><a class="header-anchor" href="#二、按锁的粒度分类-核心分类方式"><span><strong>二、按锁的粒度分类（核心分类方式）</strong></span></a></h1><p>锁的粒度指锁定资源的范围，粒度越小，并发度越高（锁冲突概率低），但锁管理开销越大；反之则并发度低，开销小。MySQL支持三种粒度的锁：全局锁、表级锁、行级锁。</p><h2 id="_2-1-全局锁-锁定整个mysql实例" tabindex="-1"><a class="header-anchor" href="#_2-1-全局锁-锁定整个mysql实例"><span><strong>2.1 全局锁：锁定整个MySQL实例</strong></span></a></h2><h3 id="核心定义" tabindex="-1"><a class="header-anchor" href="#核心定义"><span>核心定义</span></a></h3><p>全局锁是粒度最大的锁，锁定整个MySQL实例（所有数据库、所有表）。锁定期间，整个实例只读（SELECT除外，DML、DDL、创建/删除数据库等写操作全部阻塞）。</p><h3 id="常用命令" tabindex="-1"><a class="header-anchor" href="#常用命令"><span>常用命令</span></a></h3><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 加全局锁（Flush tables with read lock）</span></span>
<span class="line"><span>FLUSH TABLES WITH READ LOCK;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 释放全局锁（两种方式）</span></span>
<span class="line"><span>UNLOCK TABLES; -- 主动释放</span></span>
<span class="line"><span>quit; -- 断开会话，自动释放</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="核心使用场景-全库逻辑备份" tabindex="-1"><a class="header-anchor" href="#核心使用场景-全库逻辑备份"><span>核心使用场景：全库逻辑备份</span></a></h3><p>场景：运维需要对全库进行逻辑备份（如mysqldump），加全局锁确保备份期间数据一致（避免备份过程中数据被修改）。</p><p>注意：InnoDB引擎支持事务的一致性快照（--single-transaction参数），备份时无需加全局锁（利用MVCC实现无锁备份），全局锁更适用于MyISAM等不支持事务的引擎。</p><h3 id="坑点-阻塞所有写操作-影响业务" tabindex="-1"><a class="header-anchor" href="#坑点-阻塞所有写操作-影响业务"><span>坑点：阻塞所有写操作，影响业务</span></a></h3><p>生产环境中，全局锁会导致所有写操作（下单、更新数据等）阻塞，仅适合低峰期或只读实例使用。InnoDB备份优先用：<code>mysqldump -u root -p --single-transaction 数据库名 &gt; 备份文件.sql</code></p><h2 id="_2-2-表级锁-锁定整张表" tabindex="-1"><a class="header-anchor" href="#_2-2-表级锁-锁定整张表"><span><strong>2.2 表级锁：锁定整张表</strong></span></a></h2><p>表级锁是粒度中等的锁，锁定整张表。特点：<strong>锁管理开销小、加锁快</strong>，但并发度低（同一时间仅一个事务能写表）。MySQL中所有引擎都支持表级锁。</p><p>常见表级锁：表锁（读锁/写锁）、元数据锁（MDL锁）、意向锁（IS/IX，表级锁，协调表锁与行锁）。</p><h3 id="_2-2-1-表锁-table-lock-读锁-写锁" tabindex="-1"><a class="header-anchor" href="#_2-2-1-表锁-table-lock-读锁-写锁"><span>2.2.1 表锁（Table Lock）：读锁/写锁</span></a></h3><h4 id="核心特性" tabindex="-1"><a class="header-anchor" href="#核心特性"><span>核心特性</span></a></h4><ul><li><strong>表级读锁（Shared Lock，S锁）：多个事务可同时加读锁，读锁之间兼容；读锁阻塞写锁（加读锁后，其他事务无法加写锁）。</strong></li><li><strong>表级写锁（Exclusive Lock，X锁）：仅一个事务可加写锁，写锁之间互斥、写锁阻塞读锁（加写锁后，其他事务无法加读/写锁）。</strong></li></ul><h4 id="常用命令-1" tabindex="-1"><a class="header-anchor" href="#常用命令-1"><span>常用命令</span></a></h4><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 加表级读锁</span></span>
<span class="line"><span>LOCK TABLES 表名 READ;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 加表级写锁</span></span>
<span class="line"><span>LOCK TABLES 表名 WRITE;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 释放表锁（两种方式）</span></span>
<span class="line"><span>UNLOCK TABLES; -- 主动释放</span></span>
<span class="line"><span>quit; -- 断开会话，自动释放</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="使用场景" tabindex="-1"><a class="header-anchor" href="#使用场景"><span>使用场景</span></a></h4><p>适合读多写少、写操作耗时短的场景（如统计报表生成、批量更新小表）。InnoDB引擎中，表锁并发度低，优先用行级锁；MyISAM引擎默认用表锁。</p><h3 id="_2-2-2-元数据锁-mdl锁-保护表结构" tabindex="-1"><a class="header-anchor" href="#_2-2-2-元数据锁-mdl锁-保护表结构"><span>2.2.2 元数据锁（MDL锁）：保护表结构</span></a></h3><h4 id="核心定义-1" tabindex="-1"><a class="header-anchor" href="#核心定义-1"><span>核心定义</span></a></h4><p>MDL锁（Metadata Lock）是MySQL 5.5+引入的表级锁，自动添加、自动释放，无需手动操作。核心作用：<strong>保护表结构（元数据）的一致性</strong>，避免“查询过程中表结构被修改”（如查询时删字段）。</p><h4 id="mdl锁的自动添加规则" tabindex="-1"><a class="header-anchor" href="#mdl锁的自动添加规则"><span>MDL锁的自动添加规则</span></a></h4><ul><li><strong>执行SELECT、INSERT、UPDATE、DELETE时，自动加MDL读锁（多个事务可同时加，互不阻塞）；</strong></li><li><strong>执行ALTER TABLE、DROP TABLE、RENAME TABLE等DDL操作时，自动加MDL写锁（仅一个事务可加，写锁与读锁、写锁与写锁互斥）。</strong></li></ul><h4 id="核心坑点-长事务导致mdl写锁阻塞-完整闭环-复现→排查→解决→预防" tabindex="-1"><a class="header-anchor" href="#核心坑点-长事务导致mdl写锁阻塞-完整闭环-复现→排查→解决→预防"><span>核心坑点：长事务导致MDL写锁阻塞（完整闭环：复现→排查→解决→预防）</span></a></h4><h5 id="步骤1-复现mdl阻塞" tabindex="-1"><a class="header-anchor" href="#步骤1-复现mdl阻塞"><span>步骤1：复现MDL阻塞</span></a></h5><p>场景：生产库中t_user表有一个长事务（执行了SELECT，持有MDL读锁），持续10分钟未提交。此时运维执行<code>ALTER TABLE t_user ADD COLUMN phone VARCHAR(20)</code>（需加MDL写锁），会被长事务的MDL读锁阻塞。后续所有对t_user表的查询/更新（需加MDL读锁）都会排队阻塞，导致业务雪崩。</p><p>复现步骤：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 会话1（长事务，持有MDL读锁）</span></span>
<span class="line"><span>START TRANSACTION;</span></span>
<span class="line"><span>SELECT * FROM t_user; -- 执行后不提交，持有MDL读锁</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 会话2（运维，执行DDL）</span></span>
<span class="line"><span>ALTER TABLE t_user ADD COLUMN phone VARCHAR(20); -- 被阻塞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 会话3（业务查询，被阻塞）</span></span>
<span class="line"><span>SELECT * FROM t_user; -- 排队等待MDL读锁，阻塞</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="步骤2-排查mdl阻塞" tabindex="-1"><a class="header-anchor" href="#步骤2-排查mdl阻塞"><span>步骤2：排查MDL阻塞</span></a></h5><p>执行<code>show processlist;</code>，查看进程状态：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>Id | User | Host       | db   | Command | Time | State                                   | Info</span></span>
<span class="line"><span>---|------|------------|------|---------|------|----------------------------------------|----------------------------------------</span></span>
<span class="line"><span>10 | root | localhost  | test | Sleep   | 600  |                                        | NULL（会话1的长事务，Sleep状态但持有锁）</span></span>
<span class="line"><span>11 | root | localhost  | test | Query   | 300  | Waiting for table metadata lock         | ALTER TABLE t_user ADD COLUMN phone...（会话2）</span></span>
<span class="line"><span>12 | root | localhost  | test | Query   | 200  | Waiting for table metadata lock         | SELECT * FROM t_user（会话3）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>排查结论：进程10是长事务，持有t_user表的MDL读锁，阻塞了进程11（DDL）和进程12（查询）。</p><h5 id="步骤3-解决方案" tabindex="-1"><a class="header-anchor" href="#步骤3-解决方案"><span>步骤3：解决方案</span></a></h5><ol><li><strong>优先沟通：找到业务方，确认进程10的长事务用途，督促其提交/回滚；</strong></li><li><strong>紧急处理：若无法终止长事务，执行</strong><code>kill 10;</code><strong>（终止进程10，事务回滚，释放MDL读锁）；</strong></li><li><strong>后续优化：用</strong><code>pt-online-schema-change</code><strong>工具（无锁改表）替代ALTER TABLE，避免MDL锁阻塞。</strong></li></ol><h5 id="步骤4-预防措施" tabindex="-1"><a class="header-anchor" href="#步骤4-预防措施"><span>步骤4：预防措施</span></a></h5><ul><li><strong>生产环境禁止长事务，设置</strong><code>innodb_transaction_timeout=300</code><strong>（5分钟超时）；</strong></li><li><strong>DDL操作优先在低峰期执行；</strong></li><li><strong>MySQL 8.0+版本补充特性：引入更多ONLINE DDL特性，部分DDL操作（如快速加列）仅在开始和结束瞬间持有MDL写锁，中间会降级为MDL读锁，大幅降低阻塞影响。</strong></li></ul><h2 id="_2-3-行级锁-innodb的核心锁-并发之王" tabindex="-1"><a class="header-anchor" href="#_2-3-行级锁-innodb的核心锁-并发之王"><span><strong>2.3 行级锁：InnoDB的核心锁（并发之王）</strong></span></a></h2><p>表级锁虽然开销小，但并发度低，无法满足电商订单、秒杀等高并发场景的需求。而InnoDB引擎独有的行级锁，通过最小化锁定粒度（仅锁定单条数据行），能大幅提升并发性能，成为高并发场景的核心选择。接下来详细拆解行级锁的实现与实战。</p><p>行级锁是InnoDB引擎独有的锁，粒度最小（锁定单条数据行），特点是：<strong>并发度高、锁冲突概率低</strong>，但锁管理开销大、可能产生死锁。仅在事务中生效（BEGIN/COMMIT之间），事务结束后自动释放。</p><p>生产核心坑点：行级锁的实现依赖索引！无索引或索引失效时，InnoDB无法利用索引过滤数据，会被迫进行全表扫描，访问每条记录时都会加锁（含所有间隙），其效果等同于表锁，但开销甚至比直接加表锁更大，必须重点规避。</p><p>关键补充：从源码角度看，InnoDB并没有像SQL Server那样显式的“锁升级（Lock Escalation）”机制（即达到一定阈值自动转为表锁）。上述“行锁变表锁”的本质是无索引导致全表扫描加锁，而非显式锁升级。</p><h3 id="_2-3-1-行级锁的类型-基于锁属性" tabindex="-1"><a class="header-anchor" href="#_2-3-1-行级锁的类型-基于锁属性"><span>2.3.1 行级锁的类型（基于锁属性）</span></a></h3><p>行级锁按属性分为共享锁（S锁/读锁）和排他锁（X锁/写锁），与表级锁的S/X锁逻辑一致，但锁定粒度为行：</p><ul><li><strong>共享锁（S锁）：允许事务读取数据，多个事务可同时持有同一行的S锁（读-读兼容）；S锁阻塞X锁（读-写互斥）。 用法：</strong><code>SELECT ... LOCK IN SHARE MODE;</code><strong>（事务内执行，提交/回滚后释放）</strong></li><li><strong>排他锁（X锁）：允许事务修改/删除数据，仅一个事务可持有同一行的X锁（写-写互斥）；X锁阻塞S锁和其他X锁（写-读、写-写均互斥）。 用法：</strong><code>SELECT ... FOR UPDATE;</code>** 或 DML（INSERT/UPDATE/DELETE）自动加X锁（事务内生效）**</li></ul><h3 id="_2-3-2-行锁算法-基于锁定范围" tabindex="-1"><a class="header-anchor" href="#_2-3-2-行锁算法-基于锁定范围"><span>2.3.2 行锁算法（基于锁定范围）</span></a></h3><p>InnoDB通过三种锁算法实现行级锁，核心目的是平衡“数据一致性”和“并发性能”，解决幻读等并发问题：</p><h4 id="_1-记录锁-record-lock-锁定单条记录" tabindex="-1"><a class="header-anchor" href="#_1-记录锁-record-lock-锁定单条记录"><span>1. 记录锁（Record Lock）：锁定单条记录</span></a></h4><ul><li><strong>定义：锁定表中具体的一条行记录，仅对存在的记录生效。</strong></li><li><strong>适用场景：唯一索引（主键、唯一键）的等值查询（如</strong><code>WHERE id=1</code><strong>）。</strong></li><li><strong>实战案例：t_user表id为主键，事务A执行</strong><code>SELECT * FROM t_user WHERE id=1 FOR UPDATE</code><strong>，仅锁定id=1的行，其他行不受影响。</strong></li></ul><h4 id="_2-间隙锁-gap-lock-锁定索引间隙-防止插入" tabindex="-1"><a class="header-anchor" href="#_2-间隙锁-gap-lock-锁定索引间隙-防止插入"><span>2. 间隙锁（Gap Lock）：锁定索引间隙（防止插入）</span></a></h4><p>核心价值：解决幻读问题！幻读是指同一事务内多次查询同一范围，其他事务插入新行导致查询结果行数变化，间隙锁通过锁定间隙阻止插入，从而避免幻读。</p><ul><li><strong>定义：锁定“两个索引之间的间隙”（或首行之前、末行之后的间隙），不锁定具体行记录，核心作用是防止其他事务插入新行；补充：当事务A持有间隙锁时，事务B插入数据会被阻塞，此时事务B会在内存中生成“插入意向锁（Insert Intention Lock）”并进入等待状态。理解插入意向锁对排查SHOW ENGINE INNODB STATUS中的死锁日志至关重要。</strong></li><li><strong>适用场景：非唯一索引的等值查询、范围查询；</strong></li><li><strong>关键补充（Supremum pseudo-record）：当查询范围超过当前表中最大值时，InnoDB会锁定（max_id, +∞）的间隙（最大伪记录区间），防止其他事务插入更大ID的记录，彻底避免幻读。</strong></li><li><strong>实战案例：t_user表age为普通索引（值：10,24,32,45），事务A执行</strong><code>SELECT * FROM t_user WHERE age BETWEEN 20 AND 30 FOR UPDATE</code><strong>，会锁定间隙（10,24）；若执行</strong><code>SELECT * FROM t_user WHERE age &gt; 45 FOR UPDATE</code><strong>，会锁定（45, +∞）的最大伪记录间隙，此时无法插入age=50的行。</strong></li></ul><h4 id="_3-临键锁-next-key-lock-记录锁-间隙锁" tabindex="-1"><a class="header-anchor" href="#_3-临键锁-next-key-lock-记录锁-间隙锁"><span>3. 临键锁（Next-Key Lock）：记录锁+间隙锁</span></a></h4><p>定义：临键锁=记录锁+间隙锁，锁定“左开右闭”的区间（如(10,24]），是InnoDB的默认行锁算法（REPEATABLE READ隔离级别下）。</p><p>核心规则（关键修正，必记）：</p><ul><li><strong>唯一索引的等值查询：临键锁降级为记录锁（仅锁定匹配行，不锁间隙）；</strong></li><li><strong>唯一索引的范围查询：仍为临键锁（锁定范围+间隙）；</strong></li><li><strong>非唯一索引的等值/范围查询：均为临键锁。</strong></li></ul><p>记忆口诀：唯一等值降记录，唯一范围仍临键，非唯一全是临键锁。</p><h3 id="行级锁实战案例-完整闭环" tabindex="-1"><a class="header-anchor" href="#行级锁实战案例-完整闭环"><span>行级锁实战案例（完整闭环）</span></a></h3><h4 id="实战案例1-用行锁解决库存超卖问题-复现→分析→解决→验证" tabindex="-1"><a class="header-anchor" href="#实战案例1-用行锁解决库存超卖问题-复现→分析→解决→验证"><span>实战案例1：用行锁解决库存超卖问题（复现→分析→解决→验证）</span></a></h4><p>场景：电商秒杀场景，t_stock表存储商品库存（id主键，goods_id商品ID，stock库存数量），需避免多个用户同时下单导致库存为负。</p><h5 id="步骤1-复现超卖问题" tabindex="-1"><a class="header-anchor" href="#步骤1-复现超卖问题"><span>步骤1：复现超卖问题</span></a></h5><p>准备数据：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>CREATE TABLE t_stock (</span></span>
<span class="line"><span>idINT PRIMARY KEY AUTO_INCREMENT,</span></span>
<span class="line"><span>  goods_id INTNOTNULLUNIQUE,</span></span>
<span class="line"><span>  stock INTNOTNULLDEFAULT0</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>INSERTINTO t_stock (goods_id, stock) VALUES (1001, 1); -- 初始库存1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用两个会话同时执行无锁代码：</p><p>问题代码（无锁，会超卖）：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 会话1（用户A下单）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>SELECT stock FROM t_stock WHERE goods_id=1001;  -- 查到stock=1</span></span>
<span class="line"><span>UPDATE t_stock SET stock=stock-1WHERE goods_id=1001;  -- 执行后stock=0</span></span>
<span class="line"><span>-- 暂不提交</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 会话2（用户B下单，同时执行）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>SELECT stock FROM t_stock WHERE goods_id=1001;  -- 未提交读隔离级别下也查到stock=1</span></span>
<span class="line"><span>UPDATE t_stock SET stock=stock-1WHERE goods_id=1001;  -- 执行后stock=-1</span></span>
<span class="line"><span>COMMIT;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>复现结果：两个会话都执行成功，stock变为-1，超卖问题产生。</p><h5 id="步骤2-问题分析" tabindex="-1"><a class="header-anchor" href="#步骤2-问题分析"><span>步骤2：问题分析</span></a></h5><p>无锁情况下，多个事务可同时读取并修改同一行数据，缺乏并发控制，导致库存计数错误。需通过排他锁（X锁）锁定目标行，确保同一时间仅一个事务能修改。</p><h5 id="步骤3-解决方案-加x锁-避免并发修改" tabindex="-1"><a class="header-anchor" href="#步骤3-解决方案-加x锁-避免并发修改"><span>步骤3：解决方案（加X锁，避免并发修改）</span></a></h5><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 会话1（用户A下单）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>-- 加X锁锁定该商品行，其他事务需等待锁释放</span></span>
<span class="line"><span>SELECT stock FROM t_stock WHERE goods_id=1001FORUPDATE;  </span></span>
<span class="line"><span>IF stock &gt; 0 THEN</span></span>
<span class="line"><span>UPDATE t_stock SET stock=stock-1WHERE goods_id=1001;</span></span>
<span class="line"><span>-- 生成订单...</span></span>
<span class="line"><span>COMMIT;</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>-- 库存不足，提示用户</span></span>
<span class="line"><span>ROLLBACK;</span></span>
<span class="line"><span>ENDIF;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 会话2（用户B下单，同时执行）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>SELECT stock FROM t_stock WHERE goods_id=1001FORUPDATE;  -- 被会话1的X锁阻塞</span></span>
<span class="line"><span>-- 会话1提交后，会话2查询到stock=0，执行ELSE逻辑，回滚</span></span>
<span class="line"><span>ROLLBACK;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="步骤4-验证结果" tabindex="-1"><a class="header-anchor" href="#步骤4-验证结果"><span>步骤4：验证结果</span></a></h5><p>执行后查询t_stock：<code>SELECT stock FROM t_stock WHERE goods_id=1001;</code>，stock=0，无超卖；会话2被阻塞直到会话1提交，确保了数据一致性。</p><p>关键：goods_id需建立索引（如唯一索引），否则无索引导致全表扫描加锁，效果等同于表锁，所有商品秒杀都会阻塞。</p><h4 id="实战案例2-无索引导致全表扫描加锁-复现→分析→解决→验证" tabindex="-1"><a class="header-anchor" href="#实战案例2-无索引导致全表扫描加锁-复现→分析→解决→验证"><span>实战案例2：无索引导致全表扫描加锁（复现→分析→解决→验证）</span></a></h4><p>场景：t_user表（id主键，age无索引），事务A执行更新操作未指定索引，导致全表扫描加锁（效果等同于表锁），阻塞其他事务。</p><h5 id="步骤1-复现问题" tabindex="-1"><a class="header-anchor" href="#步骤1-复现问题"><span>步骤1：复现问题</span></a></h5><p>准备数据：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>CREATE TABLE t_user (</span></span>
<span class="line"><span>idINT PRIMARY KEY AUTO_INCREMENT,</span></span>
<span class="line"><span>nameVARCHAR(20) NOTNULL,</span></span>
<span class="line"><span>  age INTNOTNULL</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>INSERTINTO t_user (name, age) VALUES (&#39;张三&#39;,25), (&#39;李四&#39;,30);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>会话1（事务A，无索引更新）：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 事务A（无索引，全表扫描加锁）</span></span>
<span class="line"><span>START TRANSACTION;</span></span>
<span class="line"><span>UPDATE t_user SET name=&#39;李四&#39; WHERE age=25;  -- age无索引，全表扫描，所有行加X锁</span></span>
<span class="line"><span>-- 未提交...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>会话2（事务B，更新其他行）：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 事务B（被阻塞）</span></span>
<span class="line"><span>START TRANSACTION;</span></span>
<span class="line"><span>UPDATE t_user SET name=&#39;王五&#39; WHERE id=10;  -- 即使按主键更新，也被全表锁阻塞</span></span>
<span class="line"><span>COMMIT;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>复现结果：事务B长时间阻塞，无法执行。</p><h5 id="步骤2-问题分析-1" tabindex="-1"><a class="header-anchor" href="#步骤2-问题分析-1"><span>步骤2：问题分析</span></a></h5><p>age字段无索引，事务A执行UPDATE时触发全表扫描，InnoDB会对表中所有行加X锁（含所有间隙），其效果等同于表锁，但开销更大，导致所有对t_user表的更新都被阻塞。注意：这并非显式锁升级，而是无索引导致的全表扫描加锁。</p><h5 id="步骤3-解决方案-1" tabindex="-1"><a class="header-anchor" href="#步骤3-解决方案-1"><span>步骤3：解决方案</span></a></h5><p>为age字段建立索引，确保行锁仅锁定匹配行：<code>ALTER TABLE t_user ADD INDEX idx_age(age);</code></p><h5 id="步骤4-验证结果-1" tabindex="-1"><a class="header-anchor" href="#步骤4-验证结果-1"><span>步骤4：验证结果</span></a></h5><p>重新执行事务A和事务B：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 事务A（有索引，仅锁age=25的行）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>UPDATE t_user SETname=&#39;李四&#39;WHERE age=25;</span></span>
<span class="line"><span>-- 未提交</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 事务B（正常执行，不阻塞）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>UPDATE t_user SETname=&#39;王五&#39;WHEREid=10;</span></span>
<span class="line"><span>COMMIT;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证结果：事务B正常执行，无阻塞，仅匹配行被锁定。</p><h4 id="实战案例3-转账场景死锁-复现→排查→解决→验证" tabindex="-1"><a class="header-anchor" href="#实战案例3-转账场景死锁-复现→排查→解决→验证"><span>实战案例3：转账场景死锁（复现→排查→解决→验证）</span></a></h4><h5 id="步骤1-复现死锁" tabindex="-1"><a class="header-anchor" href="#步骤1-复现死锁"><span>步骤1：复现死锁</span></a></h5><p>准备数据：t_account表（id主键，user_id用户ID，balance余额）</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>CREATE TABLE t_account (</span></span>
<span class="line"><span>idINT PRIMARY KEY AUTO_INCREMENT,</span></span>
<span class="line"><span>  user_id INTNOTNULLUNIQUE,</span></span>
<span class="line"><span>  balance INTNOTNULLDEFAULT0</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>INSERTINTO t_account (user_id, balance) VALUES (1, 1000), (2, 1000);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>同时执行两个会话的转账SQL：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 会话1（事务A：用户1给用户2转账100元）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance-100WHERE user_id=1;  -- 持有user_id=1的X锁</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+100WHERE user_id=2;  -- 等待user_id=2的X锁</span></span>
<span class="line"><span>COMMIT;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 会话2（事务B：用户2给用户1转账50元）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance-50WHERE user_id=2;  -- 持有user_id=2的X锁</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+50WHERE user_id=1;  -- 等待user_id=1的X锁</span></span>
<span class="line"><span>COMMIT;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>复现结果：MySQL检测到死锁，终止其中一个事务（如事务B），提示“Deadlock found when trying to get lock; try restarting transaction”。</p><h5 id="步骤2-死锁排查-解读死锁日志" tabindex="-1"><a class="header-anchor" href="#步骤2-死锁排查-解读死锁日志"><span>步骤2：死锁排查（解读死锁日志）</span></a></h5><p>执行<code>SHOW ENGINE INNODB STATUS;</code>，查看死锁日志核心部分：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>------------------------</span></span>
<span class="line"><span>LATEST DETECTED DEADLOCK</span></span>
<span class="line"><span>------------------------</span></span>
<span class="line"><span>2025-12-29 10:00:00 0x7f8b12345678</span></span>
<span class="line"><span>TRANSACTION 12345, ACTIVE 2 sec starting index read</span></span>
<span class="line"><span>mysql tables in use 1, locked 1</span></span>
<span class="line"><span>LOCK WAIT 2 lock struct(s), heap size 1136, 1 row lock(s)</span></span>
<span class="line"><span>MySQL thread id 8, OS thread handle 140245678901234, query id 123 localhost root updating</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+100 WHERE user_id=2</span></span>
<span class="line"><span>TRANSACTION 67890, ACTIVE 1 sec starting index read</span></span>
<span class="line"><span>mysql tables in use 1, locked 1</span></span>
<span class="line"><span>LOCK WAIT 2 lock struct(s), heap size 1136, 1 row lock(s)</span></span>
<span class="line"><span>MySQL thread id 9, OS thread handle 140245678901235, query id 124 localhost root updating</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+50 WHERE user_id=1</span></span>
<span class="line"><span>WE ROLL BACK TRANSACTION 67890; -- 回滚事务B</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>日志解读：</p><ul><li><strong>事务12345（线程8）：持有user_id=1的X锁，等待user_id=2的X锁；</strong></li><li><strong>事务67890（线程9）：持有user_id=2的X锁，等待user_id=1的X锁；</strong></li><li><strong>形成循环等待，MySQL回滚其中一个事务（通常是执行时间短的）。</strong></li></ul><h5 id="步骤3-死锁解决方案" tabindex="-1"><a class="header-anchor" href="#步骤3-死锁解决方案"><span>步骤3：死锁解决方案</span></a></h5><ol><li><strong>统一锁顺序：所有事务按相同顺序锁定行（如按user_id升序），避免循环等待。修改后代码： \`-- 事务A、B均先锁user_id小的行 -- 事务A（用户1→用户2转账） START TRANSACTION; UPDATE t_account SET balance=balance-100 WHERE user_id=1; -- 1&lt;2，先锁1 UPDATE t_account SET balance=balance+100 WHERE user_id=2; COMMIT;</strong></li></ol><p>-- 事务B（用户2→用户1转账） START TRANSACTION; UPDATE t_account SET balance=balance-50 WHERE user_id=1; -- 先锁1（等待事务A释放） UPDATE t_account SET balance=balance+50 WHERE user_id=2; COMMIT;\`</p><ol><li><strong>减少锁持有时间：事务中仅保留核心操作（锁相关），非核心操作（如日志记录、通知推送）移到事务外；</strong></li><li><strong>设置锁超时：通过</strong><code>innodb_lock_wait_timeout</code><strong>（默认50秒）设置锁等待超时时间，避免永久阻塞；</strong></li><li><strong>死锁排查：用</strong><code>SHOW ENGINE INNODB STATUS</code><strong>查看死锁日志，分析事务持有/等待的锁资源。</strong></li></ol><h5 id="步骤4-验证结果-2" tabindex="-1"><a class="header-anchor" href="#步骤4-验证结果-2"><span>步骤4：验证结果</span></a></h5><p>修改后重新执行两个事务：事务B会先等待事务A释放user_id=1的X锁，事务A提交后，事务B获取锁继续执行，无死锁产生。</p><h1 id="三、按并发控制策略分类-悲观锁-vs-乐观锁" tabindex="-1"><a class="header-anchor" href="#三、按并发控制策略分类-悲观锁-vs-乐观锁"><span><strong>三、按并发控制策略分类：悲观锁 vs 乐观锁</strong></span></a></h1><p>悲观锁和乐观锁是两种核心的并发控制思想，并非MySQL提供的具体锁类型，而是基于锁机制或无锁机制实现的策略。悲观锁基于“冲突大概率发生”的假设，乐观锁基于“冲突小概率发生”的假设。</p><h2 id="_3-1-悲观锁-pessimistic-locking" tabindex="-1"><a class="header-anchor" href="#_3-1-悲观锁-pessimistic-locking"><span><strong>3.1 悲观锁（Pessimistic Locking）</strong></span></a></h2><h3 id="核心思想" tabindex="-1"><a class="header-anchor" href="#核心思想"><span>核心思想</span></a></h3><p>认为并发事务之间的冲突是大概率事件，因此在<strong>操作数据前先锁定资源</strong>，确保整个操作过程中资源独占，避免冲突。</p><h3 id="实现方式" tabindex="-1"><a class="header-anchor" href="#实现方式"><span>实现方式</span></a></h3><p>依赖MySQL的锁机制：行级锁（S锁/X锁）、表级锁。例如：</p><ul><li><strong>行级悲观锁：</strong><code>SELECT ... FOR UPDATE</code><strong>（X锁）、</strong><code>SELECT ... LOCK IN SHARE MODE</code><strong>（S锁）；</strong></li><li><strong>表级悲观锁：</strong><code>LOCK TABLES 表名 WRITE</code><strong>（表级X锁）。</strong></li></ul><h3 id="适用场景" tabindex="-1"><a class="header-anchor" href="#适用场景"><span>适用场景</span></a></h3><p>写多读少、冲突概率高的场景（如银行转账、订单状态修改、高并发秒杀的库存更新）。</p><h2 id="_3-2-乐观锁-optimistic-locking" tabindex="-1"><a class="header-anchor" href="#_3-2-乐观锁-optimistic-locking"><span><strong>3.2 乐观锁（Optimistic Locking）</strong></span></a></h2><p>悲观锁虽然能保证强一致性，但锁等待会降低并发度；而乐观锁基于“低冲突”假设，通过无锁操作提升并发，两者无绝对优劣，需结合业务场景选择。接下来详细拆解乐观锁的实现与实战。</p><h3 id="核心思想-1" tabindex="-1"><a class="header-anchor" href="#核心思想-1"><span>核心思想</span></a></h3><p>认为并发事务之间的冲突是小概率事件，因此<strong>操作数据前不锁定资源</strong>，直接执行操作，仅在提交事务时校验数据是否被其他事务修改（若修改则重试，未修改则提交）。</p><h3 id="实现方式-无锁机制-应用层实现" tabindex="-1"><a class="header-anchor" href="#实现方式-无锁机制-应用层实现"><span>实现方式（无锁机制，应用层实现）</span></a></h3><p>乐观锁不依赖MySQL的锁机制，由应用层通过逻辑实现，常见三种方式：</p><h4 id="_1-版本号机制-最常用" tabindex="-1"><a class="header-anchor" href="#_1-版本号机制-最常用"><span>1. 版本号机制（最常用）</span></a></h4><p>在表中新增<code>version</code>字段（版本号，初始为0），每次更新数据时版本号+1，提交时校验版本号是否与查询时一致（一致则更新，不一致则重试）。</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 1. 表结构设计（新增version字段）</span></span>
<span class="line"><span>CREATETABLE t_product (</span></span>
<span class="line"><span>idINT PRIMARY KEY AUTO_INCREMENT,</span></span>
<span class="line"><span>nameVARCHAR(50) NOTNULL,</span></span>
<span class="line"><span>  price DECIMAL(10,2) NOTNULL,</span></span>
<span class="line"><span>versionINTNOTNULLDEFAULT0-- 版本号</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 2. 乐观锁更新逻辑（查询→更新→校验版本号）</span></span>
<span class="line"><span>STARTTRANSACTION;</span></span>
<span class="line"><span>-- 步骤1：查询数据，获取当前版本号</span></span>
<span class="line"><span>SELECT price, versionFROM t_product WHEREid=1; -- 假设查询到price=100, version=0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 步骤2：更新数据，仅当版本号匹配时才更新</span></span>
<span class="line"><span>UPDATE t_product </span></span>
<span class="line"><span>SET price=90, version=version+1</span></span>
<span class="line"><span>WHEREid=1ANDversion=0; -- 校验版本号，一致则更新</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 步骤3：判断更新结果，无记录更新则说明数据被修改，重试</span></span>
<span class="line"><span>IF ROW_COUNT() = 0 THEN</span></span>
<span class="line"><span>ROLLBACK; -- 回滚，重试逻辑（应用层实现）</span></span>
<span class="line"><span>ELSE</span></span>
<span class="line"><span>COMMIT; -- 提交成功</span></span>
<span class="line"><span>ENDIF;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-时间戳机制" tabindex="-1"><a class="header-anchor" href="#_2-时间戳机制"><span>2. 时间戳机制</span></a></h4><p>与版本号机制类似，新增<code>update_time</code>字段（时间戳），提交时校验时间戳是否与查询时一致。缺点：高并发下可能因时间戳精度问题导致校验失效（如同一毫秒更新），优先用版本号。</p><h4 id="_3-mvcc-广义乐观锁" tabindex="-1"><a class="header-anchor" href="#_3-mvcc-广义乐观锁"><span>3. MVCC（广义乐观锁）</span></a></h4><p>InnoDB的MVCC（多版本并发控制）机制，通过保存数据的多个版本，实现“无锁读”（普通SELECT无需加锁），本质是广义的乐观锁（读操作不阻塞写，写操作不阻塞读）。</p><h3 id="适用场景-1" tabindex="-1"><a class="header-anchor" href="#适用场景-1"><span>适用场景</span></a></h3><p>读多写少、冲突概率低的场景（如商品浏览量统计、用户点赞、低并发的库存查询）。</p><h2 id="_3-3-乐观锁-vs-悲观锁-对比表" tabindex="-1"><a class="header-anchor" href="#_3-3-乐观锁-vs-悲观锁-对比表"><span><strong>3.3 乐观锁 vs 悲观锁 对比表</strong></span></a></h2><p>图例：✅ 优势 | ❌ 劣势</p><p><strong>对比维度</strong><br><strong>乐观锁 (Optimistic)</strong><br><strong>悲观锁 (Pessimistic)</strong></p><p>核心思想<br> &quot;冲突是小概率事件&quot;，先操作，提交时校验<br> &quot;冲突大概率发生&quot;，操作前先独占资源</p><p>实现机制<br> CAS 算法、版本号机制 (Version)、时间戳、MVCC (广义)<br> 数据库锁机制 (S锁/X锁)、SELECT...FOR UPDATE</p><p>优点<br> 吞吐量高，无锁等待，无死锁风险 ✅<br> 强一致性保证，逻辑简单，避免脏数据 ✅</p><p>缺点<br> 高冲突下重试导致 CPU 飙升，存在 ABA 问题 ❌<br> 并发度低，锁开销大，可能产生死锁 ❌</p><p>适用场景<br> 读多写少 (如：浏览量、点赞、低并发库存)<br> 写多读少 (如：银行转账、强一致性订单状态)</p><h1 id="四、按锁属性-状态分类-意向锁-is-ix锁" tabindex="-1"><a class="header-anchor" href="#四、按锁属性-状态分类-意向锁-is-ix锁"><span><strong>四、按锁属性/状态分类：意向锁（IS/IX锁）</strong></span></a></h1><p>共享锁（S锁）、排他锁（X锁）已在“行级锁”章节详细讲解，而意向锁是协调表级锁与行级锁的核心机制——表级锁与行级锁并存时，若需判断表中是否存在行锁，无意向锁则需全表遍历，效率极低。接下来补充意向锁的完整知识体系。</p><h2 id="_4-1-意向共享锁-is锁-与意向排他锁-ix锁" tabindex="-1"><a class="header-anchor" href="#_4-1-意向共享锁-is锁-与意向排他锁-ix锁"><span><strong>4.1 意向共享锁（IS锁）与意向排他锁（IX锁）</strong></span></a></h2><h3 id="核心定义与设计初衷" tabindex="-1"><a class="header-anchor" href="#核心定义与设计初衷"><span>核心定义与设计初衷</span></a></h3><p>意向锁是InnoDB引擎自动添加的<strong>表级锁</strong>，用于协调表级锁与行级锁的关系，解决“表锁与行锁冲突检查时全表遍历”的性能问题。其设计初衷是：当事务需要对表中某行加S锁或X锁时，先向表中添加对应的意向锁，后续其他事务请求表级锁时，只需判断表中是否存在对应的意向锁，即可快速确定是否存在行锁冲突，无需遍历表中所有行。</p><p>意向锁的两种核心类型（均由InnoDB自动管理，无需手动添加或释放）：</p><ul><li><strong>意向共享锁（Intention Shared Lock，IS锁）：事务准备对表中某行加S锁时，InnoDB会自动先为该表加IS锁。例如，事务执行</strong><code>SELECT * FROM t_user WHERE id=1 LOCK IN SHARE MODE</code><strong>前，会先给t_user表加IS锁。</strong></li><li><strong>意向排他锁（Intention Exclusive Lock，IX锁）：事务准备对表中某行加X锁时，InnoDB会自动先为该表加IX锁。例如，事务执行</strong><code>UPDATE t_user SET name=&#39;张三&#39; WHERE id=1</code><strong>前，会先给t_user表加IX锁。</strong></li></ul><h3 id="关键特性-为何意向锁是表级锁" tabindex="-1"><a class="header-anchor" href="#关键特性-为何意向锁是表级锁"><span>关键特性：为何意向锁是表级锁？</span></a></h3><p>意向锁的核心价值是“快速判断表中是否存在行锁”，若将其设计为行级锁，当其他事务请求表级锁时，仍需遍历表中所有行检查是否存在行锁，无法解决“全表遍历”的性能问题。而表级锁的设计，能让锁冲突检查仅通过一次表级状态判断完成，大幅提升效率。</p><p>对比示例：假设事务A已对t_user表id=1的行加X锁（自动关联IX锁），此时事务B请求表级写锁（LOCK TABLES t_user WRITE）：</p><ul><li><strong>无意向锁场景：MySQL需遍历t_user全表的每一行，检查是否存在行锁（数据量越大效率越低，百万级表可能耗时数秒）；</strong></li><li><strong>有意向锁场景：MySQL直接检查t_user表的IX锁状态（存在），立即判定冲突，拒绝事务B的表级写锁请求（耗时微秒级）。</strong></li></ul><h3 id="核心兼容规则-含is-ix与行级锁、表级锁交互" tabindex="-1"><a class="header-anchor" href="#核心兼容规则-含is-ix与行级锁、表级锁交互"><span>核心兼容规则（含IS/IX与行级锁、表级锁交互）</span></a></h3><p>图例：✅ 兼容 | ❌ 互斥 核心口诀：意向锁之间全兼容；意向锁只与表级锁互斥（意向排他互斥表级读/写，意向共享互斥表级写）。</p><p><strong>当前锁 \\ 请求锁</strong><br><strong>IS 锁 (意向共享)</strong><br><strong>IX 锁 (意向排他)</strong><br><strong>S 锁 (表级读)</strong><br><strong>X 锁 (表级写)</strong><br><strong>S 锁 (行级读)</strong><br><strong>X 锁 (行级写)</strong></p><p>IS 锁<br> ✅ 兼容<br> ✅ 兼容<br> ✅ 兼容<br> ❌ 互斥<br> ✅ 兼容<br> ❌ 互斥</p><p>IX 锁<br> ✅ 兼容<br> ✅ 兼容<br> ❌ 互斥<br> ❌ 互斥<br> ✅ 兼容<br> ❌ 互斥</p><p>S 锁 (表级)<br> ✅ 兼容<br> ❌ 互斥<br> ✅ 兼容<br> ❌ 互斥<br> ✅ 兼容<br> ❌ 互斥</p><p>X 锁 (表级)<br> ❌ 互斥<br> ❌ 互斥<br> ❌ 互斥<br> ❌ 互斥<br> ❌ 互斥<br> ❌ 互斥</p><p>关键补充：意向锁不直接阻塞行级锁，行级锁之间的冲突由行锁本身决定（如行级S锁与X锁互斥）；意向锁仅用于快速判断表级锁与行级锁的冲突。</p><h3 id="实战场景-is-ix锁的核心作用体现" tabindex="-1"><a class="header-anchor" href="#实战场景-is-ix锁的核心作用体现"><span>实战场景：IS/IX锁的核心作用体现</span></a></h3><h4 id="场景1-长事务行锁与表级备份锁的协调" tabindex="-1"><a class="header-anchor" href="#场景1-长事务行锁与表级备份锁的协调"><span>场景1：长事务行锁与表级备份锁的协调</span></a></h4><p>生产环境中，事务A（长事务）执行<code>SELECT * FROM t_order WHERE order_id=1001 FOR UPDATE</code>（对行加X锁，自动加IX锁），持续10分钟未提交。此时运维需执行全表备份，执行<code>LOCK TABLES t_order READ</code>（表级S锁）。</p><p>执行逻辑：</p><ol><li><strong>备份请求检查t_order表的意向锁状态，发现存在IX锁；</strong></li><li><strong>根据兼容规则，表级S锁与IX锁互斥，备份请求被阻塞；</strong></li><li><strong>运维通过</strong><code>show processlist</code><strong>定位到长事务A，督促业务方提交事务；</strong></li><li><strong>事务A提交后，IX锁自动释放，备份请求成功获取表级S锁，执行备份。</strong></li></ol><h4 id="场景2-多事务行锁与ddl锁的冲突协调" tabindex="-1"><a class="header-anchor" href="#场景2-多事务行锁与ddl锁的冲突协调"><span>场景2：多事务行锁与DDL锁的冲突协调</span></a></h4><p>事务B执行<code>SELECT * FROM t_user WHERE id=5 LOCK IN SHARE MODE</code>（加行级S锁，自动加IS锁），事务C执行<code>SELECT * FROM t_user WHERE id=8 LOCK IN SHARE MODE</code>（加行级S锁，自动加IS锁）。此时开发执行<code>ALTER TABLE t_user ADD COLUMN email VARCHAR(50)</code>（需加MDL写锁，本质是表级排他锁）。</p><p>执行逻辑：</p><ol><li><strong>DDL请求检查t_user表意向锁，发现存在IS锁；</strong></li><li><strong>MDL写锁与IS锁互斥，DDL请求被阻塞；</strong></li><li><strong>事务B、C提交后，IS锁释放；</strong></li><li><strong>DDL请求获取MDL写锁，完成表结构修改并释放锁。</strong></li></ol><h3 id="核心注意事项" tabindex="-1"><a class="header-anchor" href="#核心注意事项"><span>核心注意事项</span></a></h3><ul><li><strong>自动管理，无需手动操作：IS/IX锁由InnoDB自动添加和释放，事务结束（提交/回滚）后，意向锁随同行级锁一同释放，用户无需执行</strong><code>LOCK</code><strong>或</strong><code>UNLOCK</code><strong>命令。</strong></li></ul><p><strong>不直接阻塞数据读写</strong>：意向锁仅用于锁冲突的“预判断”，不直接锁定数据。例如，表中存在IS锁时，其他事务仍可正常执行SELECT、UPDATE、DELETE等数据操作（只要不涉及表级锁冲突）；即使表中有IX锁，不同事务也能对表中不同行加行级锁并正常操作，仅当请求表级锁时才会触发冲突检查。</p><h1 id="五、锁相关排查工具与命令-实战必备" tabindex="-1"><a class="header-anchor" href="#五、锁相关排查工具与命令-实战必备"><span><strong>五、锁相关排查工具与命令（实战必备）</strong></span></a></h1><p>生产环境中，锁阻塞、死锁是常见问题，掌握以下排查工具能快速定位问题根源。所有命令基于MySQL 8.0版本，可直接在客户端执行。</p><h2 id="_5-1-查看当前数据库进程与锁等待状态" tabindex="-1"><a class="header-anchor" href="#_5-1-查看当前数据库进程与锁等待状态"><span><strong>5.1 查看当前数据库进程与锁等待状态</strong></span></a></h2><h3 id="核心命令-show-processlist" tabindex="-1"><a class="header-anchor" href="#核心命令-show-processlist"><span>核心命令：show processlist;</span></a></h3><p>作用：查看当前MySQL所有连接进程的状态，包括进程ID、执行命令、等待状态、执行SQL等，快速定位阻塞进程。</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 查看所有进程（精简版）</span></span>
<span class="line"><span>show processlist;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看完整进程信息（含完整SQL）</span></span>
<span class="line"><span>show full processlist;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键状态解读（锁相关）：</p><ul><li><strong>Waiting for table metadata lock：MDL锁等待（通常由长事务持有MDL读锁，阻塞DDL操作）；</strong></li><li><strong>Waiting for row lock：行级锁等待（如事务A持有X锁，事务B请求同一行X锁）；</strong></li><li><strong>Sleep：进程处于空闲状态，但可能持有锁（长事务常见状态）。</strong></li></ul><p>排查示例：通过State字段筛选出“Waiting for table metadata lock”的进程，记录其Id（阻塞源进程），再查看对应的Info字段（执行的SQL），定位长事务所属业务。</p><h2 id="_5-2-查看innodb引擎锁详细信息" tabindex="-1"><a class="header-anchor" href="#_5-2-查看innodb引擎锁详细信息"><span><strong>5.2 查看InnoDB引擎锁详细信息</strong></span></a></h2><h3 id="核心命令-show-engine-innodb-status" tabindex="-1"><a class="header-anchor" href="#核心命令-show-engine-innodb-status"><span>核心命令：show engine innodb status;</span></a></h3><p>作用：输出InnoDB引擎的详细状态，包括死锁日志、锁结构、事务信息等，是排查死锁的核心工具。</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>show engine innodb status;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>关键信息模块（重点关注）：</p><h4 id="_1-latest-detected-deadlock-最新死锁日志" tabindex="-1"><a class="header-anchor" href="#_1-latest-detected-deadlock-最新死锁日志"><span>1. LATEST DETECTED DEADLOCK（最新死锁日志）</span></a></h4><p>包含死锁发生时间、参与死锁的事务、持有/等待的锁资源、被回滚的事务等信息。示例解读：</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>LATEST DETECTED DEADLOCK</span></span>
<span class="line"><span>------------------------</span></span>
<span class="line"><span>2025-12-29 14:30:00 0x7f8b12345678</span></span>
<span class="line"><span>TRANSACTION 12345, ACTIVE 2 sec starting index read</span></span>
<span class="line"><span>mysql tables in use 1, locked 1</span></span>
<span class="line"><span>LOCK WAIT 2 lock struct(s), heap size 1136, 1 row lock(s)</span></span>
<span class="line"><span>MySQL thread id 8, OS thread handle 140245678901234, query id 123 localhost root updating</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+100 WHERE user_id=2  -- 事务1等待的操作</span></span>
<span class="line"><span>TRANSACTION 67890, ACTIVE 1 sec starting index read</span></span>
<span class="line"><span>mysql tables in use 1, locked 1</span></span>
<span class="line"><span>LOCK WAIT 2 lock struct(s), heap size 1136, 1 row lock(s)</span></span>
<span class="line"><span>MySQL thread id 9, OS thread handle 140245678901235, query id 124 localhost root updating</span></span>
<span class="line"><span>UPDATE t_account SET balance=balance+50 WHERE user_id=1  -- 事务2等待的操作</span></span>
<span class="line"><span>WE ROLL BACK TRANSACTION 67890; -- 被回滚的事务</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>解读要点：确定两个事务的“持有锁”和“等待锁”，判断是否存在循环等待，进而优化锁顺序。</p><h4 id="_2-transactions-当前活跃事务" tabindex="-1"><a class="header-anchor" href="#_2-transactions-当前活跃事务"><span>2. TRANSACTIONS（当前活跃事务）</span></a></h4><p>查看当前未提交的活跃事务，包括事务持有锁数量、执行时间等，可定位长事务（执行时间过长的事务）。</p><h2 id="_5-3-查询锁相关系统表-精准定位锁资源" tabindex="-1"><a class="header-anchor" href="#_5-3-查询锁相关系统表-精准定位锁资源"><span><strong>5.3 查询锁相关系统表（精准定位锁资源）</strong></span></a></h2><p>MySQL 8.0提供多个系统表用于精准查询锁信息，需注意：<strong>MySQL 8.0已移除information_schema库下的innodb_locks和innodb_lock_waits表</strong>，取而代之的是performance_schema库下的data_locks和data_lock_waits表（8.0新特性），新表提供更详细的锁关联信息，可精准查询锁的类型、持有/等待进程、关联表和索引等内容。</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>-- 重要提示：MySQL 8.0 新特性（旧表innodb_locks已移除）</span></span>
<span class="line"><span>-- 1. 查看当前所有锁信息（替代原innodb_locks）</span></span>
<span class="line"><span>SELECT * FROM performance_schema.data_locks;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 2. 查看锁等待关系（替代原innodb_lock_waits）</span></span>
<span class="line"><span>-- 核心字段：blocking_engine_transaction_id（阻塞事务ID）、requesting_engine_transaction_id（请求事务ID）</span></span>
<span class="line"><span>SELECT </span></span>
<span class="line"><span>  blocking_engine_transaction_id AS blocking_trx_id,  -- 阻塞方事务ID</span></span>
<span class="line"><span>  requesting_engine_transaction_id AS requesting_trx_id, -- 请求方事务ID</span></span>
<span class="line"><span>  blocking_lock_id,  -- 阻塞方锁ID</span></span>
<span class="line"><span>  requesting_lock_id -- 请求方锁ID</span></span>
<span class="line"><span>FROM performance_schema.data_lock_waits;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 3. 结合进程表，定位阻塞源对应的SQL（适配8.0新表）</span></span>
<span class="line"><span>SELECT </span></span>
<span class="line"><span>  p.id,  -- 进程ID</span></span>
<span class="line"><span>  p.user,</span></span>
<span class="line"><span>  p.host,</span></span>
<span class="line"><span>  p.db,</span></span>
<span class="line"><span>  p.info,  -- 执行的SQL</span></span>
<span class="line"><span>  l.lock_type,  -- 锁类型（TABLE/ROW）</span></span>
<span class="line"><span>  l.lock_mode,  -- 锁模式（X/S/IS/IX等）</span></span>
<span class="line"><span>  l.lock_table  -- 锁定的表</span></span>
<span class="line"><span>FROM </span></span>
<span class="line"><span>  information_schema.processlist p</span></span>
<span class="line"><span>JOIN </span></span>
<span class="line"><span>  performance_schema.data_locks l ON p.id = SUBSTRING_INDEX(l.lock_id, &#39;:&#39;, 1)</span></span>
<span class="line"><span>WHERE </span></span>
<span class="line"><span>  p.state LIKE &#39;Waiting for%&#39;; -- 筛选等待锁的进程</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用场景：当show processlist无法精准定位锁资源时，通过系统表可获取更详细的锁关联信息，快速找到阻塞根源。</p><h1 id="六、生产环境锁优化策略-避坑指南" tabindex="-1"><a class="header-anchor" href="#六、生产环境锁优化策略-避坑指南"><span><strong>六、生产环境锁优化策略（避坑指南）</strong></span></a></h1><p>锁问题的核心优化思路：<strong>减少锁持有时间、缩小锁粒度、避免锁冲突、合理选择锁策略</strong>。结合前文案例，总结以下实战优化方案：</p><h2 id="_6-1-核心优化原则-缩小锁粒度" tabindex="-1"><a class="header-anchor" href="#_6-1-核心优化原则-缩小锁粒度"><span><strong>6.1 核心优化原则：缩小锁粒度</strong></span></a></h2><ul><li><strong>必须为查询条件字段建索引：行级锁依赖索引，无索引或索引失效会导致全表扫描加锁（效果等同于表锁）。例如，更新/删除操作的WHERE条件字段（如goods_id、user_id）必须建立索引（主键/唯一索引/普通索引）。</strong></li><li><strong>避免全表扫描和全表更新：禁止执行无WHERE条件的UPDATE/DELETE（如UPDATE t_user SET status=1），此类操作会对表中所有行加X锁，导致并发阻塞。</strong></li><li><strong>使用精准查询条件：尽量用唯一索引的等值查询（如WHERE id=100），使临键锁降级为记录锁，减少锁定范围；避免非唯一索引的范围查询（如WHERE age&gt;30），此类查询会产生间隙锁/临键锁，扩大锁定范围。</strong></li></ul><h2 id="_6-2-关键优化-减少锁持有时间" tabindex="-1"><a class="header-anchor" href="#_6-2-关键优化-减少锁持有时间"><span><strong>6.2 关键优化：减少锁持有时间</strong></span></a></h2><ul><li><strong>控制事务大小，避免长事务：事务中仅包含核心操作（如锁定数据、更新数据），非核心操作（如日志记录、通知推送、调用外部接口）移到事务外。例如，订单创建事务仅包含“扣减库存+生成订单”，后续的短信通知单独执行。</strong></li><li><strong>及时提交/回滚事务：禁止事务长时间处于未提交状态（如事务开启后等待用户输入），设置innodb_transaction_timeout=300（5分钟超时），自动回滚超时未提交的事务。</strong></li><li><strong>避免在事务中执行慢查询：慢查询会延长事务执行时间，导致锁持有时间增加。优化慢查询（如添加索引、优化SQL结构），避免事务内执行耗时超过1秒的查询。</strong></li></ul><h2 id="_6-3-避免锁冲突-统一锁顺序-合理设计业务" tabindex="-1"><a class="header-anchor" href="#_6-3-避免锁冲突-统一锁顺序-合理设计业务"><span><strong>6.3 避免锁冲突：统一锁顺序+合理设计业务</strong></span></a></h2><ul><li><strong>统一事务的锁顺序：多个事务操作同一组表/行时，按固定顺序锁定资源，避免循环等待导致死锁。例如，转账场景中，所有事务均按user_id升序锁定账户（先锁user_id小的账户）。</strong></li><li><strong>避免并发更新同一行数据：高并发场景（如秒杀、点赞），避免多个事务同时更新同一行（如库存表的同一条记录）。可通过“分库分表”（如库存按商品ID哈希分表）或“乐观锁”（版本号机制）替代悲观锁，减少冲突。</strong></li><li><strong>读写分离，降低读锁冲突：高读并发场景，采用“主从复制+读写分离”架构，读请求路由到从库，写请求路由到主库。从库通过MVCC实现无锁读，避免读请求对主库写锁的阻塞。</strong></li></ul><h2 id="_6-4-合理选择锁策略与mysql特性" tabindex="-1"><a class="header-anchor" href="#_6-4-合理选择锁策略与mysql特性"><span><strong>6.4 合理选择锁策略与MySQL特性</strong></span></a></h2><ul><li><strong>按业务场景选择悲观/乐观锁：读多写少、低冲突场景（如商品浏览量）用乐观锁（版本号）；写多读少、高冲突场景（如银行转账）用悲观锁（行级X锁）。</strong></li><li><strong>利用MySQL 8.0 ONLINE DDL特性：执行表结构修改（如加列、改字段类型）时，优先使用MySQL 8.0的ONLINE DDL特性，部分操作（如快速加列）仅在开始和结束瞬间持有MDL写锁，中间降级为读锁，大幅降低阻塞影响。</strong></li><li><strong>避免使用表级锁：InnoDB引擎优先使用行级锁，避免手动执行LOCK TABLES（表级锁）。若需批量更新小表，可在低峰期执行，或用行级锁分批更新（如按ID分段更新）。</strong></li><li><strong>合理设置隔离级别：默认隔离级别为REPEATABLE READ（支持间隙锁/临键锁，避免幻读）；若业务无需避免幻读，可降低隔离级别为READ COMMITTED，此时InnoDB会禁用间隙锁（仅保留记录锁），减少锁冲突（注意：需接受不可重复读）。</strong></li></ul><h2 id="_6-5-运维监控-提前预警锁问题" tabindex="-1"><a class="header-anchor" href="#_6-5-运维监控-提前预警锁问题"><span><strong>6.5 运维监控：提前预警锁问题</strong></span></a></h2><ul><li><strong>监控锁等待指标：通过Prometheus+Grafana等监控工具，监控MySQL的锁相关指标，如锁等待次数、锁等待时间、长事务数量等，设置阈值预警（如锁等待时间超过5秒报警）。</strong></li><li><strong>定期审计慢查询和长事务：开启MySQL慢查询日志（slow_query_log=1），定期分析慢查询；通过information_schema.innodb_trx表定期排查长事务，及时优化业务代码。</strong></li></ul><h1 id="七、总结" tabindex="-1"><a class="header-anchor" href="#七、总结"><span><strong>七、总结</strong></span></a></h1><p>MySQL锁是并发控制的核心，掌握锁的类型、实现原理和实战排查优化，是保障高并发业务稳定运行的关键。本笔记核心要点总结：</p><ul><li><strong>锁粒度选择：高并发优先用行级锁（InnoDB独有），低并发/小表可用表级锁，全库备份可用全局锁（InnoDB优先用--single-transaction无锁备份）。</strong></li><li><strong>行锁关键规则：行锁依赖索引，无索引导致全表扫描加锁；唯一等值降记录锁，唯一范围仍临键锁，非唯一全是临键锁；间隙锁（含最大伪记录区间）解决幻读。</strong></li><li><strong>锁问题排查：show processlist定位阻塞进程，show engine innodb status查看死锁日志，information_schema系统表精准查询锁资源。</strong></li><li><strong>优化核心：缩小锁粒度、减少锁持有时间、统一锁顺序、按场景选锁策略，结合MySQL 8.0特性（ONLINE DDL、读写分离）提升并发性能。</strong></li></ul><p>锁的使用没有绝对最优方案，需结合业务场景（并发量、冲突概率、一致性要求）灵活选择，最终实现“数据一致性”与“并发性能”的平衡。</p><p><strong>觉得有用的兄弟，点个赞，收藏起来，万一下次面试就用上了呢！</strong></p><p><strong>关注公众号【Fox爱分享】，只讲那些书上不写的实战坑。</strong></p>`,224)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};